<script setup>
import {ref,computed,onMounted,watch,nextTick} from 'vue';import {useRoute,useRouter} from 'vue-router';import {get,post,patch,del,message,imageUrl,api} from '../services/api.js';import {useAuth,useSaved,useUi} from '../stores/index.js';import RestaurantCard from '../components/restaurants/RestaurantCard.vue';import ConfirmDialog from '../components/ConfirmDialog.vue';import QRCode from 'qrcode';import Icon from '../components/common/Icon.vue';import BaseModal from '../components/common/BaseModal.vue';import GradeBadge from '../components/restaurants/GradeBadge.vue';import StarRating from '../components/common/StarRating.vue';import {restaurantImage,dishImage} from '../utils/formatters.js';
const route=useRoute(),router=useRouter(),auth=useAuth(),saved=useSaved(),ui=useUi(),r=ref(null),reviews=ref([]),similar=ref([]),error=ref(''),busy=ref(false),review=ref({rating:5,title:'',comment:''}),sort=ref('newest'),editing=ref(null),deleting=ref(false),reporting=ref(false),report=ref({reason:'',type:'restaurant_info',details:''}),suggesting=ref(false),suggestion=ref({field:'profile.openingHours',proposedValue:''}),ownerMessage=ref(''),qr=ref(''),lightbox=ref(''),promptM=ref(null),delReview=ref(null),reviewTouched=ref(false),reviewDone=ref(false),reportErr=ref(''),suggestErr=ref(''),ownerErr=ref(''),acting=ref(false);const canEdit=computed(()=>auth.canManage&&(auth.user?.role==='admin'||auth.user?._id===r.value?.ownerId));const address=computed(()=>r.value?[r.value.address?.building,r.value.address?.street,r.value.borough,r.value.address?.zipcode,r.value.country].filter(Boolean).join(' '):'');
async function loadReviews(){try{const id=route.params.id;const [reviewList,record]=await Promise.all([get('/restaurants/'+id+'/reviews',{sort:sort.value}),get('/restaurants/'+id)]);if(route.params.id!==id)return;reviews.value=reviewList.data;r.value=record.data;}catch{}}
async function load(){error.value='';r.value=null;try{r.value=(await get('/restaurants/'+route.params.id)).data;saved.visited(r.value._id);document.title=r.value.name+' | BonAppé Find';let session=sessionStorage.getItem('bonappefind_session');if(!session){session=crypto.randomUUID();sessionStorage.setItem('bonappefind_session',session);}post('/restaurants/'+r.value._id+'/view',{sessionId:session}).catch(()=>{});await loadReviews();similar.value=(await get('/restaurants/'+r.value._id+'/similar')).data;qr.value=await QRCode.toDataURL(location.href,{width:140,margin:1});const script=document.getElementById('restaurant-jsonld')||document.createElement('script');script.id='restaurant-jsonld';script.type='application/ld+json';script.textContent=JSON.stringify({'@context':'https://schema.org','@type':'Restaurant',name:r.value.name,description:r.value.profile.story,servesCuisine:r.value.cuisine,address:{'@type':'PostalAddress',streetAddress:address.value,addressCountry:r.value.country},priceRange:r.value.profile.priceRange});document.head.append(script);}catch(e){error.value=message(e);}}
const commentErr=computed(()=>reviewTouched.value&&review.value.comment.trim().length<5?'Tell other diners a little about your meal (at least 5 characters).':'');
async function submitReview(){reviewTouched.value=true;if(commentErr.value){document.getElementById('review-comment')?.focus();return;}busy.value=true;try{if(editing.value)await patch('/reviews/'+editing.value,review.value);else await post('/restaurants/'+r.value._id+'/reviews',review.value);ui.toast('Thank you! Your review has been saved.');editing.value=null;review.value={rating:5,title:'',comment:''};reviewTouched.value=false;reviewDone.value=true;setTimeout(()=>reviewDone.value=false,2500);await loadReviews();}catch(e){ui.toast(message(e),'error');}finally{busy.value=false;}}
async function reviewAction(v,action){if(action==='report'||action==='reply'){promptM.value={type:action,v,text:'',err:''};return;}if(action==='delete'){delReview.value=v;return;}try{if(action==='helpful'){await post('/reviews/'+v._id+'/helpful');ui.toast('Marked as helpful.');}await loadReviews();}catch(e){ui.toast(message(e),'error');}}
async function confirmDelReview(){acting.value=true;try{await del('/reviews/'+delReview.value._id);delReview.value=null;await loadReviews();ui.toast('Review deleted.');}catch(e){ui.toast(message(e),'error');}finally{acting.value=false;}}
async function sendPrompt(){const m=promptM.value;if(m.text.trim().length<3){m.err=m.type==='report'?'Tell us what looks wrong (at least 3 characters).':'Write a short reply (at least 3 characters).';document.getElementById('prompt-text')?.focus();return;}acting.value=true;try{await post('/reviews/'+m.v._id+'/'+m.type,m.type==='report'?{reason:m.text.trim()}:{text:m.text.trim()});promptM.value=null;await loadReviews();ui.toast(m.type==='report'?'Report sent for review.':'Reply posted.');}catch(e){m.err=message(e);}finally{acting.value=false;}}
async function remove(){try{const record=r.value;await del('/restaurants/'+record._id);deleting.value=false;ui.toast('Restaurant deleted.','success',async()=>{await post('/restaurants/'+record._id+'/restore');ui.toast('Restaurant restored.');});router.push('/restaurants');}catch(e){ui.toast(message(e),'error');}}
async function share(){try{if(navigator.share)await navigator.share({title:r.value.name,url:location.href});else{await navigator.clipboard.writeText(location.href);ui.toast('Link copied to your clipboard.');}}catch{ui.toast('We could not copy the link. Please copy it from the address bar.','error');}}
async function submitReport(){reportErr.value=report.value.reason.trim().length<5?'Tell us what needs checking (at least 5 characters).':'';if(reportErr.value)return;try{await post('/restaurants/'+r.value._id+'/reports',report.value);reporting.value=false;ui.toast('Report sent for review.');}catch(e){ui.toast(message(e),'error');}}
async function submitSuggestion(){suggestErr.value=suggestion.value.proposedValue.trim()?'':'Enter the correct value.';if(suggestErr.value)return;try{await post('/restaurants/'+r.value._id+'/suggestions',suggestion.value);suggesting.value=false;ui.toast('Suggested edit sent.');}catch(e){ui.toast(message(e),'error');}}
async function sendOwner(){ownerErr.value=ownerMessage.value.trim().length<10?'Please write at least 10 characters.':'';if(ownerErr.value)return;try{await post('/restaurants/'+r.value._id+'/contact-owner',{message:ownerMessage.value});ownerMessage.value='';ui.toast('Message sent to the owner.');}catch(e){ui.toast(message(e),'error');}}
async function upload(e){const file=e.target.files[0];if(!file)return;const fd=new FormData();fd.append('image',file);fd.append('alt','Photo supplied for '+r.value.name);try{await api.post('/restaurants/'+r.value._id+'/images',fd);await load();ui.toast('Image uploaded.');}catch(e){ui.toast(message(e),'error');}}
watch(()=>route.params.id,load);onMounted(load);function print(){window.print();}
const lightboxDialog=ref(null);let lightboxFocus;watch(lightbox,async value=>{if(value){lightboxFocus=document.activeElement;await nextTick();lightboxDialog.value?.showModal();}else lightboxFocus?.focus();});
</script>
<template><div class="container section"><p v-if="error" class="error-box" role="alert">{{error}}</p><div v-else-if="!r" class="skeleton" style="min-height:420px"></div><template v-else><nav class="bread" aria-label="Breadcrumb"><RouterLink to="/">Home</RouterLink> / <RouterLink to="/restaurants">Restaurants</RouterLink> / {{r.name}}</nav><div class="page-head row between"><div><p class="eyebrow muted">{{r.country}} · {{r.cuisine}}</p><h1>{{r.name}}</h1><p>{{r.profile.tagline}}</p><div class="row"><span class="badge">{{r.borough}}</span><span class="badge">{{r.profile.priceRange||'$'.repeat(r.priceLevel)}}</span><span v-if="r.isClaimed" class="badge">Claimed listing</span><span v-if="r.openNow!==null" class="badge">{{r.openNow?'Open now':'Closed now'}}</span></div></div><div class="row no-print"><button @click="saved.toggle(r._id)" class="secondary heart-btn" :class="{saved:saved.saved.includes(r._id)}" :aria-pressed="saved.saved.includes(r._id)"><Icon name="heart" :size="18" :fill="saved.saved.includes(r._id)"/>{{saved.saved.includes(r._id)?'Saved':'Save'}}</button><button @click="saved.comparison(r._id)" class="secondary toggle" :class="{active:saved.compare.includes(r._id)}" :aria-pressed="saved.compare.includes(r._id)"><Icon name="compare" :size="18"/>{{saved.compare.includes(r._id)?'In comparison':'Compare'}}</button><button @click="share" class="secondary"><Icon name="share" :size="18"/>Share</button><RouterLink v-if="canEdit" :to="'/restaurants/'+r._id+'/edit'" class="btn">Edit</RouterLink><button v-if="canEdit" class="cta" @click="deleting=true">Delete</button></div></div><p v-if="r.status!=='open'" class="notice">This restaurant is {{r.status.replaceAll('_',' ')}}.</p><p v-if="r.approvalStatus!=='approved'" class="notice">Approval status: {{r.approvalStatus}}. This listing is not yet public.</p><div class="split"><div class="stack"><div class="detail-hero"><img :src="restaurantImage(r,imageUrl)" :alt="r.cuisine+' dining inspiration for '+r.name" class="profile-cover" @error="$event.target.src=dishImage(r.cuisine)"><div class="hero-meta"><span class="badge"><Icon name="pin" :size="14"/>{{r.borough}}</span><span class="badge"><Icon name="dollar" :size="14"/>{{r.profile.priceRange||'$'.repeat(r.priceLevel)}}</span><StarRating v-if="r.reviewCount" :value="r.avgRating||0" :count="r.reviewCount" class="on-photo"/></div></div><section class="card pad"><h2>The story behind {{r.name}}</h2><p>{{r.profile.story}}</p><h3>Order these first</h3><ul class="list"><li v-for="dish in r.profile.signatureDishes" :key="dish">{{dish}}</li></ul><h3>Did you know?</h3><p>{{r.profile.funFact||'Ask the staff about the story behind the house specialty.'}}</p></section><section v-if="r.gallery?.length" class="card pad"><h2>Gallery</h2><div class="grid"><button v-for="image in r.gallery" :key="image.url" class="secondary" @click="lightbox=imageUrl(image.url)"><img :src="imageUrl(image.url)" :alt="image.alt" loading="lazy"></button></div></section><section v-if="r.menuPreview?.length" class="card pad"><h2>Menu preview</h2><p v-for="m in r.menuPreview" :key="m.name">{{m.name}} <b>{{m.price}}</b> · {{m.description}}</p><p class="small muted">Sample prices only. Confirm currency and current prices with the restaurant.</p></section><section class="card pad"><h2>Grades and scores</h2><table><thead><tr><th>Date</th><th>Grade</th><th>Score</th></tr></thead><tbody><tr v-for="(g,i) in r.grades" :key="i"><td>{{g.date?.slice(0,10)}}</td><td><GradeBadge :grade="g.grade"/></td><td>{{g.score}}</td></tr></tbody></table><p v-if="!r.grades?.length">No grades have been recorded for this restaurant yet.</p><h3>Quality Score: {{r.totalScore}}</h3><p class="small muted">The total of recorded scores. Totals above 90 appear on Best Quality. This is not an official rating.</p></section><section class="card pad"><div class="row between"><h2>What diners say</h2><select v-model="sort" aria-label="Sort reviews" style="width:160px" @change="loadReviews"><option value="newest">Newest</option><option value="highest">Highest rating</option><option value="lowest">Lowest rating</option></select></div><div v-for="stars in [5,4,3,2,1]" :key="stars" class="row small" style="margin-bottom:8px"><span>{{stars}} ★</span><div class="bar" :style="{width:(reviews.filter(v=>v.rating===stars).length/Math.max(1,reviews.length)*70)+'%'}"></div><span>{{reviews.filter(v=>v.rating===stars).length}}</span></div><article v-for="(v,vi) in reviews" :key="v._id" class="review" :style="{'--i':vi}"><b>{{v.author}} · {{'★'.repeat(v.rating)}}</b><p>{{v.title}}</p><p>{{v.comment}}</p><p v-if="v.ownerReply?.text" class="notice">Owner reply: {{v.ownerReply.text}}</p><div v-if="auth.user" class="row no-print"><button class="secondary small" @click="reviewAction(v,'helpful')">Helpful ({{v.helpfulUsers?.length||0}})</button><button class="secondary small" @click="reviewAction(v,'report')">Report</button><button v-if="auth.user._id===v.user" class="secondary small" @click="editing=v._id;review={rating:v.rating,title:v.title,comment:v.comment}">Edit review</button><button v-if="auth.user._id===v.user||auth.staff" class="secondary small" @click="reviewAction(v,'delete')">Delete review</button><button v-if="canEdit" class="secondary small" @click="reviewAction(v,'reply')">Reply</button></div></article><p v-if="!reviews.length">No reviews yet. Be the first to share your meal.</p><form v-if="auth.user" novalidate @submit.prevent="submitReview" class="stack no-print review-form"><h3>{{editing?'Edit your review':'Write a review'}}</h3><p v-if="reviewDone" class="form-status success" role="status">Thank you! Your review was posted.</p><p v-if="!auth.user.emailVerified">Verify your email first through <RouterLink to="/account">your account</RouterLink>.</p><div><label for="review-title">Title</label><input id="review-title" v-model="review.title" maxlength="100"></div><div><label for="review-rating">Rating (1 to 5)</label><select id="review-rating" v-model.number="review.rating"><option v-for="n in 5" :key="n" :value="n">{{n}} stars</option></select></div><div><label for="review-comment">Your comment</label><textarea id="review-comment" v-model="review.comment" maxlength="300" :aria-invalid="!!commentErr" aria-describedby="review-comment-msg" @blur="reviewTouched=true"></textarea><div class="msg-row"><p id="review-comment-msg" v-if="commentErr" class="field-msg">{{commentErr}}</p><span class="char-count">{{review.comment.length}} / 300</span></div></div><div class="row"><button :class="{'is-loading':busy}" :disabled="busy"><span>{{editing?'Save review':'Post review'}}</span></button><button v-if="editing" type="button" class="secondary" @click="editing=null;review={rating:5,title:'',comment:''}">Cancel edit</button></div></form><p v-else><RouterLink to="/login">Log in</RouterLink> to write a review.</p></section></div><aside class="stack"><section class="card pad"><h2>At a glance</h2><dl><template v-for="[label,value] in [['Cuisine',r.cuisine],['Region',r.borough],['Country',r.country],['City',r.city],['Opening hours',r.profile.openingHours],['Dress code',r.profile.dressCode],['Reservations',r.profile.reservations],['Dietary information',r.profile.dietaryOptions?.join(', ')],['Amenities',r.amenities?.join(', ')],['Payment methods',r.paymentMethods?.join(', ')]]" :key="label"><dt class="small muted">{{label}}</dt><dd>{{value||'Please confirm with the restaurant.'}}</dd></template></dl><div class="row"><span v-for="x in r.dietary" :key="x" class="badge">{{x}}</span></div><p class="small muted">Last updated: {{r.updatedAt?.slice(0,10)}}</p></section><section class="card pad"><h2>Find it here</h2><p>{{address}}</p><div class="stack"><a class="btn" :href="'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(address)" target="_blank" rel="noopener noreferrer">Get Directions</a><a v-if="r.profile.phone" :href="'tel:'+r.profile.phone">{{r.profile.phone}}</a><a v-if="r.profile.email" :href="'mailto:'+r.profile.email">Email the restaurant</a><a v-if="r.profile.website" :href="r.profile.website" target="_blank" rel="noopener noreferrer">Visit website</a><a v-for="(url,key) in r.social" v-show="url" :key="key" :href="url" target="_blank" rel="noopener noreferrer">{{key}}</a><RouterLink :to="'/countries/'+r.countrySlug">Read the {{r.country}} guide →</RouterLink></div></section><section class="card pad no-print"><h3>Help keep this listing accurate</h3><RouterLink v-if="auth.user?.role==='owner'&&!r.isClaimed" :to="'/restaurants/'+r._id+'/claim'" class="btn secondary">Claim this restaurant</RouterLink><div v-if="auth.user" class="row" style="margin-top:14px"><button class="secondary small" @click="reporting=!reporting">Report information</button><button class="secondary small" @click="suggesting=!suggesting">Suggest an edit</button></div><Transition name="expand-fade"><form v-if="reporting" class="stack" novalidate @submit.prevent="submitReport"><div class="field"><label for="report-reason">What needs checking?</label><textarea id="report-reason" v-model="report.reason" maxlength="500" :aria-invalid="!!reportErr" @input="reportErr=''"></textarea><p v-if="reportErr" class="field-msg">{{reportErr}}</p></div><select v-model="report.type" aria-label="Report type"><option value="restaurant_info">Wrong information</option><option value="closed">Restaurant closed</option></select><button>Send report</button></form></Transition><Transition name="expand-fade"><form v-if="suggesting" class="stack" novalidate @submit.prevent="submitSuggestion"><label for="suggest-field">Field</label><select id="suggest-field" v-model="suggestion.field"><option v-for="f in ['name','cuisine','borough','city','profile.openingHours','profile.phone']" :key="f">{{f}}</option></select><div class="field"><label for="suggest-value">Correct value</label><input id="suggest-value" v-model="suggestion.proposedValue" maxlength="120" :aria-invalid="!!suggestErr" @input="suggestErr=''"><p v-if="suggestErr" class="field-msg">{{suggestErr}}</p></div><button>Suggest edit</button></form></Transition></section><form v-if="auth.user&&r.ownerId" class="card pad stack no-print" novalidate @submit.prevent="sendOwner"><h3>Contact restaurant owner</h3><div class="field"><label for="owner-message">Message</label><textarea id="owner-message" v-model="ownerMessage" maxlength="1000" :aria-invalid="!!ownerErr" @input="ownerErr=''"></textarea><p v-if="ownerErr" class="field-msg">{{ownerErr}}</p></div><button>Send message</button></form><div v-if="canEdit" class="card pad no-print"><label for="gallery-upload">Add a gallery image (JPEG, PNG or WebP; up to 5 MB)</label><input id="gallery-upload" type="file" accept="image/jpeg,image/png,image/webp" @change="upload"></div><div class="card pad"><img :src="qr" alt="QR code linking to this restaurant profile" width="140" height="140"><button class="secondary no-print" @click="print" style="margin-top:15px">Print profile</button></div></aside></div><section v-if="similar.length" class="section"><h2>You might also like</h2><div class="grid"><RestaurantCard v-for="s in similar" :key="s._id" :restaurant="s"/></div></section><ConfirmDialog v-if="deleting" title="Delete this restaurant?" :text="r.name+' will be moved to Trash.'" confirm-label="Delete" @cancel="deleting=false" @confirm="remove"/><ConfirmDialog v-if="delReview" title="Delete this review?" text="The review will be removed permanently." confirm-label="Delete review" :busy="acting" @cancel="delReview=null" @confirm="confirmDelReview"/><BaseModal v-if="promptM" :title="promptM.type==='report'?'Report this review':'Reply to this review'" :dirty="!!promptM.text.trim()" @close="promptM=null"><form novalidate @submit.prevent="sendPrompt"><div class="field"><label for="prompt-text">{{promptM.type==='report'?'Why are you reporting this review?':'Your reply'}}</label><textarea id="prompt-text" v-model="promptM.text" maxlength="500" :aria-invalid="!!promptM.err" @input="promptM.err=''"></textarea><p v-if="promptM.err" class="field-msg">{{promptM.err}}</p></div><div class="row" style="justify-content:flex-end"><button :class="{'is-loading':acting}" :disabled="acting"><span>{{promptM.type==='report'?'Send report':'Post reply'}}</span></button></div></form></BaseModal><dialog ref="lightboxDialog" v-if="lightbox" class="lightbox" aria-label="Image preview" @cancel.prevent="lightbox=''" @click="e=>{if(e.target===lightboxDialog)lightbox=''}"><button class="lb-close" @click="lightbox=''" aria-label="Close image preview">Close ×</button><img :src="lightbox" alt="Restaurant gallery image"></dialog></template></div></template>
<style scoped>.detail-hero{position:relative;border-radius:var(--radius-lg);overflow:hidden;box-shadow:var(--shadow-lg);animation:fade-up .7s var(--ease) both}.detail-hero .profile-cover{border-radius:0;max-height:460px;transition:transform 1.2s var(--ease)}.detail-hero:hover .profile-cover{transform:scale(1.04)}.hero-meta{position:absolute;left:16px;bottom:16px;display:flex;gap:8px;flex-wrap:wrap;align-items:center}.on-photo{background:var(--candle);color:var(--black-raspberry);border-radius:var(--radius-pill);padding:3px 12px}.profile-cover{width:100%;max-height:440px;object-fit:cover;border-radius:12px}dd{margin:2px 0 18px}.review{border-bottom:1px solid var(--color-border);padding:20px 0;margin-bottom:20px}.lightbox::backdrop{background:#14130add}.lightbox{position:fixed;inset:0;background:transparent;border:0;width:100%;height:100%;max-width:100%;max-height:100%;z-index:90;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:12px;padding:24px}.lightbox img{max-height:80vh}</style>
